All sources checked (plan.md, specs/rules-v2.md, tests/DomainTests/Program.cs, design-input/*). BR-03 requires flipping RefundRequested to `order.Paid` for the not-yet-shipped/not-yet-cancelled case, while BR-04 (already-cancelled) must stay unaffected. No signature or API changes needed.

```json
{
  "status": "proposal",
  "reason": "BR-03（specs/rules-v2.md 第11行）：已付款、未出貨、未取消時 Cancel 應回傳 RefundRequested=true；未付款則 false。原本 Cancellation.cs 第21行固定回傳 false，導致 SC-03 FAIL。修正為 RefundRequested: order.Paid，並保留既有的 Shipped 分支（BR-02，SC-02/05）與 Cancelled 分支（BR-04，SC-06/07：已取消再次取消維持原狀、不重複退款）。型別簽名（Order、CancellationResult、Cancellation.Cancel、Transitioned）未變動，未新增套件或外部呼叫，僅改 Domain 檔案，符合 CLAUDE.md 範圍限制。本次未執行測試，由外層 runner 執行。",
  "content": "namespace OrderCancel.Domain;

public record Order(bool Shipped, bool Paid, bool Cancelled);
public record CancellationResult(Order Order, bool RefundRequested);

public static class Cancellation
{
    public static CancellationResult Cancel(Order order)
    {
        // 已出貨的訂單不可取消：維持原訂單，Cancelled 不變，不丟例外（specs/rules-v2.md BR-02）
        if (order.Shipped)
        {
            return new CancellationResult(order, RefundRequested: false);
        }

        // 已取消的訂單再次取消：維持原狀、不重複退款、不丟例外（specs/rules-v2.md BR-04）
        if (order.Cancelled)
        {
            return new CancellationResult(order, RefundRequested: false);
        }

        // 尚未出貨、尚未取消的訂單可以取消，回傳 Cancelled=true（specs/rules-v2.md BR-01）
        // 已付款則提出退款要求，未付款則不提出（specs/rules-v2.md BR-03，Owner 於 v2 推翻 v1 決定）
        var cancelledOrder = order with { Cancelled = true };
        return new CancellationResult(cancelledOrder, RefundRequested: order.Paid);
    }

    /// 這次呼叫有沒有真的把狀態從未取消改成已取消（通知的分母；非業務規則）。
    public static bool Transitioned(Order before, CancellationResult after) => !before.Cancelled && after.Order.Cancelled;
}
"
}
